/**
 * config.mjs — loads launcher.config.json for the Node tooling.
 * (The Worker and the Rust side read the same file directly; the browser UI
 * gets src/config.js, generated by tools/configure.mjs.)
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import os from "node:os";
import { fileURLToPath } from "node:url";

export const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
export const CONFIG_PATH = path.join(ROOT, "launcher.config.json");

export function loadConfig() {
  const cfg = JSON.parse(readFileSync(CONFIG_PATH, "utf8"));
  const missing = [];
  for (const k of ["studio.name", "launcher.productName", "launcher.identifier", "launcher.installFolder", "launcher.codePrefix", "launcher.keyDir",
                   "server.apiUrl", "server.customDomain", "server.workerName", "server.bucket", "links.newsFeed"]) {
    if (k.split(".").reduce((o, p) => (o == null ? o : o[p]), cfg) == null) missing.push(k);
  }
  if (missing.length) throw new Error(`launcher.config.json is missing: ${missing.join(", ")}`);
  return cfg;
}

export const config = loadConfig();
/** Private key folder, e.g. %USERPROFILE%\.wpg */
export const keyDir = path.join(os.homedir(), config.launcher.keyDir);
